mapper.update:

UPDATE KEP_VISITHD A
SET
	 A.NOTE					= #{st_cstmr_remark}
	,A.CHANGE_DATE		= TO_CHAR(SYSDATE,'YYYYMMDD')
	,A.CHANGE_TIME		= TO_CHAR(SYSDATE,'HH24MISS')
	,A.CHANGE_USER_ID	= #{st_user_id}
WHERE A.BUYER =  #{com_code}
AND A.STATUS <> 'D'


UPDATE KEP_VISITDT A
SET A.STATUS = 'D'
WHERE A.BUYER = #{BUYER}
AND A.ADD_DATE = #{ADD_DATE}
AND A.ADD_TIME = #{ADD_TIME}
AND A.STATUS <> 'D'
